INSERT INTO clues (dish_id, order_index, text) VALUES
(1,1,'A pasta made in the time it takes the water to boil.'),
(1,2,'Roman legend ties it to charcoal workers, or to American rations after the war.'),
(1,3,'Purists riot when you add cream; the internet riots when chefs add peas.'),
(1,4,'Cured pork cheek and pecorino cheese are tossed with hot pasta and raw egg.'),
(1,5,'Italy''s glossy Roman pasta, slicked yellow and speckled black with pepper.'),
(2,1,'A pie with so few toppings that nothing can hide.'),
(2,2,'Born in Naples, where street ovens fed the working class for centuries.'),
(2,3,'Named for a queen who visited in 1889 and picked the patriotic option.'),
(2,4,'You stretch dough thin, dress it with tomato, mozzarella and basil, and blast it in a wood oven.'),
(2,5,'Italy''s blistered wood-fired round, red and white under torn green leaves.'),
(3,1,'A tray bake where the family argues over the crispy corner piece.'),
(3,2,'Emilia-Romagna claims the definitive version, rich with ragù and béchamel.'),
(3,3,'A certain orange cartoon cat would steal it right off your table.'),
(3,4,'Wide, flat pasta sheets are stacked with meat sauce and cheese.'),
(3,5,'Italy''s baked slab, served in squares that hold their shape on the plate.'),
(4,1,'A rice dish the color of a gold coin.'),
(4,2,'Legend says a glassmaker''s apprentice colored it with a stained-glass pigment in 1574.'),
(4,3,'Traditionally served alongside osso buco.'),
(4,4,'The cook steeps saffron threads in hot broth and ladles it into the rice a spoonful at a time.'),
(4,5,'Italy''s deep-gold saffron rice, loose enough to spread slowly across the plate.'),
(5,1,'Assembled in a dish and left overnight in the fridge, not an oven.'),
(5,2,'Cooks in the Veneto built it in the 1960s, which is remarkably young for a classic.'),
(5,3,'Its name is a promise: "pick me up".'),
(5,4,'Coffee-soaked ladyfingers layered with mascarpone cream and cocoa.'),
(5,5,'The most famous spoon dessert in Italy, heavy on the espresso.'),
(6,1,'A hot sandwich you have to eat with cutlery.'),
(6,2,'First appeared on a Paris café menu around 1910.'),
(6,3,'Proust name-checked it; add a fried egg on top and it becomes a "madame".'),
(6,4,'Ham and gruyère under a blanket of béchamel, grilled until bubbling.'),
(6,5,'A café lunch in France, golden on top, with ham and cheese hiding beneath a toasty lid.'),
(7,1,'A summer vegetable pot that tastes better the day after.'),
(7,2,'A peasant stew from Provence, once dismissed by chefs as too humble.'),
(7,3,'A 2007 animated rat made it fine-dining famous.'),
(7,4,'Eggplant, zucchini, peppers and tomato, stewed or fanned in neat spirals.'),
(7,5,'The French summer vegetable stew, glossy with oil and no meat in sight.'),
(8,1,'Arrives under a lid of cheese welded to the rim of the bowl.'),
(8,2,'Once sold at dawn in the Les Halles market to porters and night owls.'),
(8,3,'Julia Child taught America to make it on public television.'),
(8,4,'Slow-caramelized onions in beef broth, capped with bread and molten gruyère.'),
(8,5,'France''s dark broth under a raft of bread and a blistered cheese lid.'),
(9,1,'Cold and silky underneath, with a hard sweet lid on top.'),
(9,2,'France, Spain''s crema catalana, and Cambridge''s Trinity College all claim it.'),
(9,3,'The 2001 film Amélie made cracking its top one of cinema''s small joys.'),
(9,4,'Vanilla custard hiding under a torched sugar shell.'),
