(10,2,'Folk tales trace it to Julius Caesar and a defiant Gallic chieftain''s rooster.'),
(10,3,'Another dish Julia Child made famous in American kitchens.'),
(10,4,'Chicken braises slowly in red wine alongside bacon, mushrooms and pearl onions.'),
(10,5,'The French wine braise, meat falling off the bone into a dark purple sauce.'),
(11,1,'Cooked outdoors in a pan wide enough to feed the whole family.'),
(11,2,'Born in Valencia''s rice paddies, cooked by farmhands over orange-wood fires.'),
(11,3,'Cooks name it for the wide shallow pan, and stirring it is the one thing you must not do.'),
(11,4,'Saffron rice studded with shrimp and mussels, prized for its crusty bottom.'),
(11,5,'One wide pan of rice goes down in the middle of a Spanish party, and spoons come out.'),
