(70,4,'Rice is simmered for hours in broth until it breaks down into a silky porridge, topped with shredded meat.'),
(70,5,'China''s plain white bowl, eaten hot with pickles and fried dough alongside.'),
(71,1,'Meat hung on hooks behind the glass, chopped to order with a cleaver.'),
