(169,1,'A puffed batter side that shares a county''s name.'),
(169,2,'18th-century cooks in northern England poured batter under roasting meat to catch the dripping fat.'),
(169,3,'A proper Sunday roast will not go out without it, and the batter needs a screaming-hot tin.'),
