(215,2,'Frugal home cooks there began baking sausages directly into a pancake-like batter to stretch the meat.'),
(215,3,'Its whimsical name pokes fun at how the sausages seem to peek out of the risen batter like little heads.'),
(215,4,'Sausages are baked directly into a Yorkshire-pudding-style batter until puffed and golden.'),
(215,5,'Britain''s roasting-tin supper, sausages half-sunk in a crisp, billowing crust, gravy on the side.'),
(216,1,'A pan-fried cake that crackles at the edges.'),
(216,2,'Frugal households there invented this dish to use up leftover vegetables from a Sunday roast.'),
(216,3,'Its name literally describes the noises the pan makes as the vegetables fry.'),
(216,4,'Leftover mashed potato and cabbage are mashed together and pan-fried until crisp and browned.'),
(216,5,'Britain''s brown-crusted wedge of Sunday leftovers, served with cold meat or a fried egg.'),
(217,1,'Thin enough to crackle, blistered black at the edges.'),
(217,2,'Farmers there once used this thin dough to test their wood-fired oven''s temperature before baking bread.'),
(217,3,'Its name literally translates to "flame cake," referencing that fiery oven origin.'),
(217,4,'A paper-thin dough is topped with cream, onion, and bacon, then baked until blistered.'),
(217,5,'A cream, onion and bacon flatbread from the Franco-German border.'),
(218,1,'Sunday dinner with red cabbage and dumplings on the side.'),
(218,2,'Home cooks there wrapped thin beef around bacon and pickle, a way to make a small roast serve a crowd.'),
(218,3,'Toothpicks or string traditionally hold each little roll together while it braises.'),
(218,4,'Thin beef slices are spread with mustard, bacon, onion, and pickle, then rolled and braised.'),
(218,5,'Dark rolled bundles, sliced to show the spiral inside, on a German Sunday table.'),
(219,1,'Lumpy little noodles, no two the same shape.'),
(219,2,'Home cooks there scrape a soft dough through a special press or board directly into boiling water.'),
(219,3,'Its irregular little dumpling shape has earned it the nickname "little sparrows" in German.'),
(219,4,'A thick egg-and-flour batter is pressed into boiling water, forming small soft noodles, then buttered.'),
(219,5,'Soft, irregular little noodles served in Germany with melted cheese, onions or gravy.'),
(220,1,'Eaten standing up at a market stall, mustard in one hand.'),
(220,2,'Regional German butchers have guarded their own seasoned sausage recipes for centuries, some dating to medieval guild records.'),
(220,3,'German beer festivals sell it by the mile, split down the middle in a hard roll.'),
(220,4,'Seasoned ground pork is stuffed into casing, grilled, and served in a roll with mustard.'),
(220,5,'Germany''s browned sausage in a crusty bun, a stripe of yellow mustard down the length.'),
(221,1,'A birthday cake with cherries on top and a boozy secret inside.'),
(221,2,'Bakers in that shadowy region layered chocolate sponge with the cherry brandy distilled locally.'),
(221,3,'German law protects the name, so a version without the cherry brandy cannot use it.'),
(221,4,'Chocolate sponge layers are soaked in cherry brandy, filled with whipped cream and cherries, and shaved chocolate.'),
(221,5,'Germany''s tall dark cake with a ring of whipped cream and cherries crowning the top.'),
(222,1,'A thick egg dish from an Iberian country, despite sharing a name with a flatbread.'),
(222,2,'Farmers there stretched scarce eggs by folding in abundant potatoes during a 19th-century food shortage.'),
(222,3,'Bars serve it at room temperature in wedges, and the argument is whether onion belongs.'),
(222,4,'Sliced potato and onion cook slowly in olive oil, then bind with beaten egg into a thick cake.'),
(222,5,'Spain''s thick golden wedge, tender inside, with a glass of wine and a toothpick.'),
(223,1,'A fried potato tapa from the same Iberian country as the potato omelette above.'),
(223,2,'Madrid tapas bars popularized dousing fried potato chunks in a fiery paprika sauce mid-20th century.'),
(223,3,'Its name literally means "fierce potatoes," a nod to the spicy sauce.'),
(223,4,'Fried potato cubes take a smoky paprika-tomato sauce and a garlicky mayonnaise.'),
(223,5,'Golden chunks under red sauce and white sauce, the plate to order at any bar in Spain.'),
(224,1,'Crisp shell, molten middle, passed across a bar counter.'),
(224,2,'Home cooks there found a way to use up leftover cured ham scraps by binding them into a creamy fried shape.'),
(224,3,'Bartenders across that country''s tapas bars measure their kitchen''s skill by how creamy this fried bite stays inside.'),
(224,4,'A thick ham-studded béchamel is chilled, breaded, and deep-fried into a crisp, creamy bite.'),
(224,5,'Spain''s golden fingers that burst with hot, creamy ham filling when bitten.'),
(225,1,'A heavy winter pot that feeds a table of hungry farmhands.'),
(225,2,'Farmhouse cooks in that region layered white beans with whatever preserved meats their pantry held.'),
(225,3,'Towns in that region still argue over whose version, with duck or without, is the authentic one.'),
(225,4,'White beans bake slowly with duck, sausage, and pork under a crust that gets broken and reformed as it cooks.'),
(225,5,'A slow-baked white bean and duck stew from the southwest of France.'),
(226,1,'A tart with a dark, sticky top that was once its bottom.'),
(226,2,'Two sisters running a hotel there supposedly caramelized apples too long, then flipped the pastry over to save it.'),
(226,3,'It''s flipped onto the serving plate tableside, revealing its caramelized fruit only at the last moment.'),
(226,4,'Apples caramelize in butter and sugar under a pastry lid, then the whole tart flips upside down to serve.'),
(226,5,'France''s shiny amber disc, apple slices packed tight under a glossy caramel crown.'),
(227,1,'A breakfast roll where the best part is buried in the middle.'),
(227,2,'Bakers there layered butter into yeasted dough, folding in dark batons before the morning bake.'),
(227,3,'French children buy it on the way to school, and the south of the country calls it something else.'),
(227,4,'Buttery laminated dough wraps two dark batons and bakes until flaky and golden.'),
(227,5,'A flaky rectangle with two dark seams running through it, from a French boulangerie.'),
(228,1,'A plate where each ingredient keeps its own corner.'),
(228,2,'Fishing families in that coastal city built this salad around their local catch and garden vegetables.'),
(228,3,'Purists there insist real versions never include cooked potato or green beans, though most restaurants add them anyway.'),
(228,4,'Tuna, hard-boiled egg, olives, and tomato arrange over lettuce with green beans and potato.'),
(228,5,'A salad from the south of France where anchovy and olive oil do the dressing''s job.'),
(229,1,'A pasta with three things in the bowl and nowhere for a mistake to hide.'),
(229,2,'Shepherds in that region carried aged cheese and peppercorns as portable rations, tossing them with pasta over a fire.'),
(229,3,'Its deceptively short ingredient list makes it one of the hardest pasta sauces to get silky instead of clumpy.'),
(229,4,'Pasta water helps melt sharp aged cheese and cracked black pepper into a creamy coating with no cream at all.'),
(229,5,'Italy''s tangle of spaghetti in a pale, glossy sauce, specked grey with pepper.'),
(230,1,'A starter whose name trips up half the people who order it.'),
(230,2,'Olive farmers there once tasted freshly pressed oil by rubbing it onto grilled bread with garlic.'),
(230,3,'The garlic gets rubbed on the hot toast, not chopped into anything.'),
(230,4,'Grilled bread is rubbed with garlic and olive oil, then piled with diced tomato and basil.'),
(230,5,'Italy''s thick toasted slices, glossy with oil, heaped with red tomato and torn basil.'),
(231,1,'A starter that is only as good as its tomato.'),
(231,2,'Cooks on that island arranged three ingredients to echo the colors of Italy''s flag.'),
(231,3,'Its red, white and green lay out the Italian flag on the plate.'),
(231,4,'Sliced tomato, fresh mozzarella, and basil leaves layer together, drizzled with olive oil.'),
(231,5,'Italy''s overlapping rounds, juicy red against milky white, fanned out on a plate with leaves.'),
(232,1,'Soft pillows that go in the pot and float when they are ready.'),
(232,2,'Home cooks there began working boiled potato into dough after the tuber arrived from the Americas centuries ago.'),
(232,3,'A fork is traditionally used to press ridges into each dumpling to help sauce cling.'),
(232,4,'Boiled potato is mashed and worked into a soft dough with flour and egg, then shaped into small dumplings.'),
(232,5,'Small ridged dumplings from Italy, each groove built to hold a spoonful of sauce.'),
(233,1,'Sold by the slice at bakeries, sweet and salty in one bite.'),
(233,2,'Sailors and dockworkers in that Mediterranean port city snacked on this slow-cooked onion tart between shifts.'),
(233,3,'Its name comes from a salted fish paste once spread beneath the onions, though anchovies now sit on top instead.'),
(233,4,'Sweet onions cook down slowly, then top a bread base with olives and anchovies.'),
(233,5,'France''s rectangular onion tart, dark with anchovy fillets and olives in a diamond pattern.');

