INSERT INTO clues (dish_id, order_index, text) VALUES
(234,1,'The first sandwich most kids learn to make on a stove.'),
(234,2,'It became a household staple during the Great Depression, when bread and cheese were cheap and filling.'),
(234,3,'Diners famously pair it with a bowl of tomato soup for dunking.'),
(234,4,'Buttered bread is griddled until golden while cheese melts gooey in the middle.'),
(234,5,'A golden griddled sandwich pulling apart into strings, an American lunch-counter default.'),
(235,1,'Cut into four triangles so it can stand up on the plate.'),
(235,2,'It first appeared in American social establishments in the late 1800s.'),
(235,3,'A frilly toothpick holds it together, and the third slice of bread is the point.'),
(235,4,'Toasted bread is stacked with poultry, bacon, lettuce, tomato and mayonnaise in two tiers.'),
(235,5,'A toasted triple-decker, quartered and pinned with picks, from American hotel menus.'),
(236,1,'A toasted sandwich that tastes of summer when the tomato is right.'),
(236,2,'It grew popular after World War II, when fresh produce became available year-round.'),
(236,3,'Its name is simply the initials of its three star ingredients.'),
(236,4,'Crisp bacon, lettuce and tomato are layered with mayonnaise on toasted bread.'),
(236,5,'America''s toasted three-letter order, red and green through the middle.'),
(237,1,'The breakfast that makes a lazy weekend feel official.'),
(237,2,'Flat cakes on hot stones date back millennia, but the fluffy leavened stack is a New World breakfast icon.'),
(237,3,'The acid in the soured milk hits the soda and makes the whole stack rise.'),
(237,4,'A batter of flour, egg and soured milk hits the griddle and flips once bubbles form.'),
(237,5,'A fluffy stack with butter sliding down it under maple syrup, the American diner breakfast.'),
(238,1,'A weekend breakfast served with a jug of syrup on the side.'),
(238,2,'Soaking stale bread in egg and milk dates to ancient Rome, and France calls it lost bread.'),
(238,3,'Cooks made it to rescue yesterday''s loaf, which is why one country calls it lost bread.'),
(238,4,'Bread is dipped in beaten egg and milk, then fried and dusted with cinnamon and sugar.'),
(238,5,'Custard-soaked slices, fried golden and dusted with sugar, called lost bread in France.'),
(239,1,'A brunch plate that became a New York City icon.'),
(239,2,'Legend credits a hungover Wall Street broker at a Manhattan hotel in the 1890s.'),
(239,3,'Hollandaise is the whole trick, and a split sauce ruins the plate.'),
(239,4,'A poached egg and ham sit on a toasted muffin under hollandaise of egg yolk, butter and lemon.'),
(239,5,'A brunch plate with yellow sauce spilling over a poached yolk, an American diner icon.'),
(240,1,'A fair-day lunch that doesn''t need a plate or a fork.'),
(240,2,'It was popularized at fairs and amusement parks in the mid-20th-century United States.'),
(240,3,'Fairgrounds sell it on a wooden stick so you can eat it walking the midway.'),
(240,4,'A sausage is skewered, dunked in a cornmeal batter, and deep-fried until crisp.'),
(240,5,'A battered sausage on a stick with mustard zigzagged down it, a fairground meal in America.'),
(241,1,'Eaten over a plate because the filling won''t stay put.'),
(241,2,'It is said to trace to a mid-1900s Midwestern cook who added tomato sauce to loose ground beef.'),
(241,3,'Its name warns that you will need extra napkins.'),
(241,4,'Ground beef is simmered with tomato, onion and pepper, then spooned onto a soft bun.'),
(241,5,'America''s saucy bun, guaranteed to end up on the plate and your hands.'),
(242,1,'A comfort dinner for the first cold night of the year.'),
(242,2,'Savory meat pies came over with European settlers and became a New World cold-weather staple.'),
(242,3,'The pastry lid is the whole trick, holding the steam in until you break it.'),
(242,4,'Chicken, carrots and peas simmer in a creamy sauce beneath a flaky crust.'),
(242,5,'A golden pastry lid over a filling that steams when broken, a cold-night dinner in America.'),
(243,1,'A bowl that goes on the stove the minute someone sneezes.'),
(243,2,'Immigrant kitchens turned it into the classic American get-well remedy.'),
(243,3,'Grandmothers serve it for a cold, and a 1978 study found the steam really does help.'),
(243,4,'Poultry simmers with pasta strands, carrot and celery in a clear golden broth.'),
(243,5,'A get-well bowl with steam coming off a clear gold surface, in kitchens across America.'),
(244,1,'A dessert so dense it needs a hot knife to cut cleanly.'),
(244,2,'Ancient Greeks made early versions, but cream cheese made this rich style famous in one U.S. metropolis.'),
(244,3,'Delis in that city built their reputations on tall, plain slices of it.'),
(244,4,'Cream cheese, sugar and eggs bake atop a buttery crushed-cracker crust.'),
(244,5,'America''s dense white wedge, cracked across the top and standing tall.'),
(245,1,'A square baked treat born in the United States.'),
(245,2,'One story credits a Chicago hotel chef asked to make a portable dessert for an 1893 world''s fair.'),
(245,3,'Bakers still argue whether the best ones are fudgy or cakey.'),
(245,4,'Melted chocolate, butter, sugar, egg and flour bake into a dense sheet, then get cut into squares.'),
(245,5,'Dark squares, fudgy in the middle and papery on top, an American bake-sale favorite.'),
(246,1,'A baked sweet invented by accident in the United States.'),
(246,2,'A Massachusetts innkeeper chopped a chocolate bar into her dough in the 1930s and a classic was born.'),
(246,3,'Its recipe famously appears on the back of the bag whose contents it needs.'),
(246,4,'Butter, sugar, flour and egg are studded with dark morsels and baked until golden.'),
(246,5,'America''s round bake, the dark morsels still soft if you get one warm.'),
(247,1,'A coffee-shop dozen that comes in a flat pink box.'),
(247,2,'Dutch settlers brought fried dough to New Amsterdam; the hole is an American refinement.'),
(247,3,'The sugar coat goes on while it is still hot, so it sets to a shell as it cools.'),
(247,4,'Yeasted dough is fried, then dipped in a thin sugar glaze that sets to a shine.'),
(247,5,'A shiny ring whose coat cracks slightly as you bite, the American coffee-shop default.'),
(248,1,'A bowl of crisp lettuce dressed to taste of garlic and salt.'),
(248,2,'An Italian restaurateur is said to have thrown it together from kitchen scraps in 1920s Tijuana.'),
(248,3,'Waiters at fancy restaurants still toss it tableside for show.'),
(248,4,'Romaine is coated in a dressing of garlic, anchovy, lemon and parmesan, then topped with croutons.'),
(248,5,'Mexico''s border-invented leaves, heavy with anchovy and cracked pepper.'),
(249,1,'A red-sauce restaurant order with spaghetti on the side.'),
(249,2,'Southern Italian immigrants adapted their eggplant original using breaded poultry in America.'),
(249,3,'Italy does not have it, and Italian-Americans built it out of a cutlet and red sauce.'),
(249,4,'A breaded chicken cutlet is topped with tomato sauce and melted mozzarella, then baked.'),
(249,5,'A cutlet under red sauce and a molten white blanket, born in Italian-American kitchens.'),
(250,1,'A pasta tossed at the table, where the sauce forms as the ribbons are turned.'),
(250,2,'A Rome restaurateur created it for his pregnant wife in the early 1900s.'),
(250,3,'It became a Hollywood favorite after honeymooning movie stars raved about it.'),
(250,4,'Ribbon pasta is tossed with butter and parmesan until it forms a creamy sauce.'),
(250,5,'Pale ribbons coated glossy with nothing but fat and cheese, a Roman restaurant dish in Italy.'),
(251,1,'A family dinner served in a big bowl and passed around.'),
(251,2,'Italian immigrants in America piled on cheap, plentiful meat in a way rare back home.'),
(251,3,'Two cartoon dogs famously share a strand of it in a Disney film.'),
(251,4,'Long pasta goes under tomato sauce and rolled balls of seasoned ground beef.'),
(251,5,'A red plate with the rolled beef sitting on top of the strands, an Italian-American classic.'),
(252,1,'A pasta that comes already stuffed, boiled in batches and lifted out gently.'),
(252,2,'Medieval Italian cooks were sealing filling inside pasta pockets by the 14th century.'),
(252,3,'A canned version made it a pantry staple in American kitchens.'),
(252,4,'Squares of pasta are sealed around a ricotta-and-spinach filling, boiled, then sauced.'),
(252,5,'Little sealed pillows floating in sauce, with crimped edges, on an Italian table.'),
(253,1,'A soup thick enough to count as a whole meal.'),
(253,2,'Ancient Romans made thick pottages from whatever the garden gave up; this is the heir.'),
(253,3,'There is no fixed recipe, only whatever the garden gave up that week.'),
(253,4,'Beans, tomatoes and seasonal vegetables simmer with small pasta in broth.'),
(253,5,'Chunky and tomato-red, an Italian soup with beans, pasta and a swirl of green oil.'),
(254,1,'A sealed pocket that stays scalding in the middle.'),
(254,2,'Naples street vendors created it as a pizza you could eat while walking.'),
(254,3,'Its name means "trouser leg," for its folded-over shape.'),
(254,4,'Pizza dough is folded over cheese and filling, sealed, and baked into a half-moon.'),
(254,5,'Italy''s puffy golden turnover, venting steam the second you cut into it.'),
(255,1,'Filled to order, so the shell stays crunchy.'),
(255,2,'It began as a carnival treat on Sicily centuries ago.'),
(255,3,'A mobster''s famous movie line advises leaving a gun but taking these.'),
(255,4,'A fried pastry shell is piped full of sweetened ricotta and studded with chocolate.'),
(255,5,'A crisp tube with cream piped in at both ends, the sweet in an Italian pastry-shop window.'),
(256,1,'A lunch that eats like a sandwich and weighs like a brick.'),
(256,2,'Its name means "little donkey" in Spanish, from that country''s north.'),
(256,3,'A California city gave rise to the oversized, foil-wrapped "mission" style.'),
(256,4,'A large flour tortilla wraps rice, beans, meat and cheese into a tight bundle.'),
(256,5,'A tight foil-wrapped log, heavy in one hand, sold at Mexican-American taquerias.'),
(257,1,'A kids'' menu favorite that grown-ups keep ordering.'),
(257,2,'Colonial cooks there filled tortillas with cheese soon after Europeans brought dairy.'),
(257,3,'Its name is built straight out of the Spanish word for cheese.'),
(257,4,'A tortilla folds over cheese and griddles until crisp and molten inside.'),
(257,5,'A browned folded round, cut into wedges that pull apart, from a Mexican kitchen.'),
(258,1,'A game-day platter eaten with the fingers and a lot of napkins.'),
(258,2,'A maître d'' named Ignacio improvised them for hungry diners in 1940s northern Mexico.'),
(258,3,'They are the loaded stadium snack piled high for the big game.'),
(258,4,'Fried tortilla chips are smothered with melted cheese, jalapeños and toppings.'),
(258,5,'A loaded pile with the chips underneath already going soft, a Mexican border invention.'),
(259,1,'A seafood handheld from the coasts of a country south of California.'),
(259,2,'They come from the Baja peninsula, where fishermen fried the day''s catch.'),
(259,3,'Surfers helped carry them north across the border in the late 20th century.'),
(259,4,'Battered or grilled white fish is tucked into a tortilla with cabbage and a lime crema.'),
(259,5,'Two folded tortillas with crisp fish, cabbage and crema, a seaside order in Mexico.'),
(260,1,'A brunch plate where the yolk is meant to run.'),
(260,2,'It was the mid-morning meal of ranch workers in that country.'),
(260,3,'Its name literally means "rancher''s eggs."'),
(260,4,'Fried eggs sit on tortillas under a warm tomato-chili salsa with beans.'),
(260,5,'Mexico''s ranch breakfast, yolks running down into black beans under red salsa.'),
(261,1,'A hangover cure served sizzling in a skillet, egg and all.'),
(261,2,'Its Nahuatl name reflects the ancient Aztec roots of the region''s cooking.'),
(261,3,'Stale tortillas become this the morning after, softened but never soggy.'),
(261,4,'Fried tortilla pieces are simmered in salsa until softened, then topped with egg and cheese.'),
(261,5,'Softened chips gone half to pieces under crema and cheese, a Mexican breakfast plate.'),
(262,1,'A chilled custard that wobbles when you set the plate down.'),
(262,2,'The Romans first baked custards; Spain gave this sweet caramel version its name.'),
(262,3,'You turn it out of the mould and the caramel runs down it as a pool.'),
(262,4,'Eggs, milk and sugar bake in a caramel-lined mold, then flip out custard-side up.'),
(262,5,'A pale dome sitting in the caramel that ran off it, a Spanish dessert-cart classic.'),
(263,1,'A cake that must sit overnight before it is ready to serve.'),
(263,2,'Mexico and Nicaragua both claim it, and a condensed-milk brand is credited with spreading it.'),
(263,3,'Its name counts the three dairy liquids it is drenched in.'),
(263,4,'Sponge cake is soaked in evaporated, condensed and regular milk, then topped with cream.'),
(263,5,'A soaked sponge so wet it pools on the plate, a Mexican birthday cake.'),
(264,1,'Rice that hisses and snaps in a smoking pan.'),
(264,2,'Cooks there invented it centuries ago as a tasty way to use day-old rice.'),
(264,3,'Yesterday''s cold leftovers work better than fresh, because dry grains stay separate.'),
(264,4,'Cold leftover grains hit a screaming wok with egg, scallion and vegetables.'),
(264,5,'Wok-tossed grains, glossy and flecked yellow with egg, a Chinese kitchen''s quickest meal.'),
(265,1,'Noodles with a crisp edge on one side and a soft tangle on the other.'),
(265,2,'Its name simply means "stir-fried noodles" in a southern Chinese dialect.'),
(265,3,'It became a defining dish of Chinese-American takeout counters.'),
(265,4,'Noodles are tossed in a hot wok with cabbage, carrot and soy sauce.'),
(265,5,'Tangled fried noodles, browned where they hit the wok, ladled from a Chinese takeout carton.'),
(266,1,'Fried pieces that stay crunchy only if you eat them fast.'),
(266,2,'It comes from the Cantonese south, where cooks balanced sugar and vinegar.'),
(266,3,'The bright orange takeout version is a long way from the Cantonese original.'),
(266,4,'Battered pieces fry hard, then get tossed with pineapple and peppers in a tart glaze.'),
(266,5,'A neon-orange takeaway bowl with pineapple bright in among it, from Chinese restaurants.'),
(267,1,'A takeout order with a dark, sticky sauce and a bit of heat.'),
(267,2,'A Taiwanese chef created it, but New York restaurants made the deep-fried version famous.'),
(267,3,'It is named for a 19th-century Chinese commander who never tasted it.'),
(267,4,'Battered chicken is fried, then coated in a sweet, garlicky, mildly spicy sauce.'),
(267,5,'A dark glossy sauce over crisp batter, the takeaway favorite of America.'),
(268,1,'A light soup built around small parcels you chase with a spoon.'),
(268,2,'Northern China''s folded dumplings traveled south and slimmed into delicate parcels.'),
(268,3,'The wrappers are rolled so thin the filling shows grey through them.'),
(268,4,'Thin wrappers around pork and shrimp float in a clear seasoned broth.'),
(268,5,'A clear bowl with pale parcels drifting about in it, ordered at Chinese restaurants everywhere.'),
(269,1,'A thick dark soup with a pepper kick and a tang you notice second.'),
(269,2,'It hails from central China, balancing heat and sourness as regional cooks prized.'),
(269,3,'White pepper brings the heat and black vinegar the sharpness, not chili.'),
(269,4,'Tofu, mushrooms and egg ribbons simmer in a broth sharpened with vinegar and pepper.'),
(269,5,'A thick dark bowl that catches you at the back of the throat, from a Chinese kitchen.'),
(270,1,'Fried to order, and meant to be eaten before it stops crackling.'),
(270,2,'Portuguese missionaries introduced batter-frying there in the 1500s.'),
(270,3,'Specialist restaurants in that country fry each piece to order at the counter.'),
(270,4,'Shrimp and vegetables are dipped in a thin, cold batter and flash-fried until lacy.'),
(270,5,'Japan''s lacy pale coating, so light you can see the shrimp through it.'),
(271,1,'Grilled meat finished with a sauce that dries to a lacquer.'),
(271,2,'Japanese cooks refined the glazing technique, and their restaurants carried it abroad.'),
(271,3,'Its name refers to the shine of the sweet-soy glaze.'),
(271,4,'Chicken is grilled and brushed with a sweet, glossy soy-and-sugar sauce.'),
(271,5,'A glossy brown glaze over grilled meat, sticky to the fingers, from a Japanese grill.'),
(272,1,'Slurped at highway rest stops and train station counters.'),
(272,2,'Legend says a Buddhist monk brought the noodle-making method there from China.'),
(272,3,'Its especially chewy, fat strands set it apart from thinner Asian noodles.'),
(272,4,'Thick wheat noodles are served in a dashi-and-soy broth topped with scallion.'),
(272,5,'Fat white noodles thick enough to feel between your teeth, from a Japanese noodle shop.'),
(273,1,'A savory broth you sip straight from the bowl, no spoon.'),
(273,2,'Fermented soybean paste has anchored the diet there for more than a millennium.'),
(273,3,'Cooks never let the paste boil, and the bowl arrives before the meal rather than with it.'),
(273,4,'Fermented soybean paste is whisked into dashi with cubes of tofu and seaweed.'),
(273,5,'A cloudy bowl with the sediment settling if you leave it standing, served in Japan.'),
(274,1,'A small dumpling dunked in a mix of soy sauce and vinegar.'),
(274,2,'Soldiers returning from mainland China brought the recipe home after World War II.'),
(274,3,'Its signature is a crispy browned bottom under a steamed top.'),
(274,4,'Thin wrappers are stuffed with pork and cabbage, then fried and steamed in one pan.'),
(274,5,'Crescent dumplings with one side browned lace-crisp, from a Japanese ramen shop.'),
(275,1,'Thin ruffled slices that cook in a minute flat on a hot dome.'),
(275,2,'Its roots reach back over a thousand years to the skewered grilled meat of the region.'),
(275,3,'Its name literally means "fire meat."'),
(275,4,'Thin beef is marinated in soy, sugar, sesame and pear, then grilled quickly.'),
(275,5,'Thin, glossy-dark beef cooked at the table, the Korean barbecue most diners try first.'),
(276,1,'Torn by hand and used as a spoon for the curry.'),
(276,2,'It was baked in the clay ovens of Persian and Mughal courts across the region.'),
(276,3,'It cooks stuck to the wall of a clay oven and peels off when it puffs.'),
(276,4,'A leavened dough of flour and yogurt is slapped onto the wall of a blazing clay oven.'),
(276,5,'A blistered teardrop, torn to push food around the plate, served alongside Indian curries.'),
(277,1,'A pale, nutty curry that rarely makes anyone sweat.'),
(277,2,'It graced the royal Mughal courts, braised gently to please emperors.'),
(277,3,'Mughal court kitchens built it, and diners order it to dodge the heat entirely.'),
(277,4,'Chicken is braised in a sauce of yogurt, cream and ground almonds.'),
(277,5,'A pale beige curry, mild and thick with ground nut, from an Indian kitchen.'),
(278,1,'A summer plate that skips the lettuce and keeps the olive oil.'),
(278,2,'Its rustic version has fed the farmers and villagers of that country for generations.'),
(278,3,'In its homeland it is simply called "village salad."'),
(278,4,'Tomato, cucumber and onion are tossed with olives and a slab of brined white cheese.'),
(278,5,'Greece''s coarse chunks glistening with oil, a block of white cheese on top and dried oregano over it.'),
(279,1,'Late-night street food, folded up in warm bread.'),
(279,2,'Vertical-spit roasting arrived there via cooks from the eastern Mediterranean.'),
(279,3,'The name comes from the Greek word for turn, like the spit it comes off.'),
(279,4,'Meat shaved from a vertical rotisserie is wrapped in pita with tomato, onion and yogurt sauce.'),
(279,5,'A paper cone of shaved meat with sauce leaking at the bottom, sold on the streets of Greece.'),
(280,1,'A sweet-hot curry that comes with a bowl of jasmine rice.'),
(280,2,'Its curry pastes reflect that kingdom''s blend of native herbs and imported chilies.'),
(280,3,'Cooks pound fresh green chilies raw for the color, and it burns hotter than the red one.'),
(280,4,'Chicken simmers in coconut milk under a paste of green chilies, basil and lime leaves.'),
(280,5,'A pale coconut bowl with oil beading across the surface, from a kitchen in Thailand.'),
(281,1,'A shiny finger of pastry that leaks when you bite it.'),
(281,2,'A 19th-century French chef put his name to the finished version.'),
(281,3,'Its name means "lightning," supposedly for how fast it is eaten.'),
(281,4,'Choux pastry is baked into a hollow log, filled with cream, and topped with chocolate.'),
(281,5,'A long glazed finger with cream squeezing out when you bite, from a French patisserie.'),
(282,1,'A pastry that crackles when you tear it and leaves crumbs behind.'),
(282,2,'It descends from an Austrian crescent roll, refined into its buttery form in Paris.'),
(282,3,'Its crescent shape gives it its name.'),
(282,4,'Butter is folded into dough again and again, then shaped and baked into flaky layers.'),
(282,5,'A flaky crescent that shatters into shards on the plate, the French breakfast pastry.'),
(283,1,'Sold hot from street carts and eaten out of a paper sleeve.'),
(283,2,'It was introduced to Americans at the 1964 New York World''s Fair.'),
(283,3,'Its extra-deep squares are built to hold pools of syrup and cream.'),
(283,4,'A yeasted batter is cooked in a griddle iron into thick squares, then dusted with sugar.'),
(283,5,'Deep-pocketed squares under a drift of powdered sugar, sold at waffle stands in Belgium.'),
(284,1,'A dessert ordered at the start of dinner because it takes its time.'),
(284,2,'French kitchens made it famous in the early 1800s, and the name means to puff up.'),
(284,3,'Open the oven too soon and it falls, which has made it a sitcom disaster for sixty years.'),
(284,4,'You fold whipped egg whites into a chocolate base and bake it so it towers above the ramekin.'),
(284,5,'A tall wobbling puff that sinks the moment it leaves the oven, a French restaurant classic.');



