INSERT INTO clues (dish_id, order_index, text) VALUES
(285,1,'Eaten from one big shared platter, working in from the edges.'),
(285,2,'Berber cooks were making it by the 13th century, and UNESCO listed it as shared heritage in 2020.'),
(285,3,'The Maghreb eats it as the Friday family meal, and half of Europe keeps the instant box.'),
(285,4,'You rub semolina into tiny pellets, then steam them over the stew they will be served with.'),
(285,5,'A mound of tiny steamed pellets piled under a spiced stew, the Friday meal in Morocco.'),
(286,1,'A dough pinched off in small pieces and used to scoop up the soup.'),
(286,2,'Pounding starchy roots into a smooth dough is one of West Africa''s oldest kitchen techniques.'),
(286,3,'It went viral on TikTok, where the running joke is that newcomers keep chewing instead of swallowing.'),
(286,4,'You pound boiled cassava and plantain until springy, roll it into a ball, and swallow it dipped in soup.'),
(286,5,'Ghana''s soft, stretchy white ball in a bowl of peppery soup, eaten with the right hand.'),
(287,1,'A smooth pale tart that trembles when the plate moves.'),
(287,2,'Dutch settlers at the Cape adapted a 17th-century Netherlands custard tart, using far more dairy and far less egg.'),
(287,3,'It has a national day in February, and Afrikaans speakers use a one-word name ending in -tert.'),
(287,4,'A pale custard set with cornflour fills a thin pastry shell, then chills under a dusting of cinnamon.'),
(287,5,'South Africa''s pale set custard in a thin crust, cinnamon dusted over it.'),
(288,1,'A sweet green-tinted brew served in a silver pot with a long spout.'),
(288,2,'British traders dumped surplus green leaf on North African ports in the 1800s; cooks added a herb and sugar.'),
(288,3,'Refusing a glass is a real insult, three rounds are traditional, and the host pours from high up.'),
(288,4,'Green leaves steep with sugar in a silver pot, and you pour from a great height into small glasses.'),
(288,5,'Morocco''s small glass of pale green, frothy tea, with sprigs of green pressed against the glass.'),
(289,1,'Griddled until it blisters, with a filling you cannot see.'),
(289,2,'It is Punjabi farmhouse food, built to fuel a whole morning in the fields.'),
(289,3,'Highway truck stops serve it all day with a slab of white butter melting on top.'),
(289,4,'Spiced mashed potato is sealed inside a wheat dough ball, rolled flat, and griddled with plenty of ghee.'),
(289,5,'India''s thick, browned flatbread, split to show a spiced potato filling, with pickle and yogurt alongside.'),
(290,1,'A street snack with a splash of cold water inside.'),
(290,2,'Cooks on the Gangetic plains made the ancestor, and it spread across India from there.'),
(290,3,'The vendor hands them over one at a time, and each must go in whole before it collapses.'),
(290,4,'Hollow crisp spheres are cracked open, filled with potato and chickpea, then dunked in chilled tangy mint-tamarind water.'),
