(347,2,'Pennsylvania Dutch settlers brought the poured-batter method from German-speaking Europe.'),
(347,3,'The smell of a carnival midway in July, sold from a trailer window.'),
(347,4,'You drizzle thin batter into hot oil in overlapping loops, fry it crisp, and bury it in powdered sugar.'),
(347,5,'A lacy fried tangle, snowed under with sugar, sold at county fairs across America.'),
(348,1,'A breakfast that is ruined by a minute of inattention.'),
(348,2,'Romans cooked them much this way, and Escoffier later codified the slow version with plenty of butter.'),
(348,3,'Chefs use it as the trial task for a new line cook, because it exposes everything.'),
(348,4,'A beaten mixture goes into melted butter over low heat, and you push it slowly around the pan into soft folds.'),
(348,5,'America''s soft yellow curds, pulled off the heat before they look done.'),
(349,1,'A lunch counter sandwich with a ham-and-pickle tang.'),
(349,2,'Cigar-factory workers in Key West and Ybor City built it from the shops that shared their street.'),
(349,3,'Tampa insists on a layer of Genoa salami, and Miami calls that heresy.'),
(349,4,'Roast pork and ham layer with Swiss cheese, mustard and dill pickles, then flatten in a press until the bread crackles.'),
(349,5,'Cuba''s flattened pressed sandwich, the crust crackling when you cut it.'),
(350,1,'Soft white bread with the crust cut off and a crunch hiding inside.'),
(350,2,'A Tokyo cutlet restaurant put fried pork between bread in the 1930s so geishas could eat one-handed.'),
(350,3,'Convenience stores sell them by the million, and wagyu versions cost as much as a steak dinner.'),
(350,4,'A panko-breaded pork cutlet is pressed with shredded cabbage between crustless slices of soft, buttered milk bread.'),
(350,5,'A crustless white sandwich eaten cold out of its wrapper, sold at Japanese convenience stores.'),
(351,1,'A diner sandwich for people who can''t choose between two orders.'),
(351,2,'Los Angeles diner lore credits Tiny Naylor in the 1940s; within a decade every coffee shop in the country had one on the board.'),
(351,3,'Ordering it marks you as a regular, because only the serious counters keep it on.'),
(351,4,'A beef round goes down with a heap of browned onions and cheese, griddled between buttered slices until dark and crisp.'),
(351,5,'A rye-bread hybrid, half burger and half grilled cheese, from an American diner flat-top.'),
(352,1,'A packed lunch assembled from two jars and a knife.'),
(352,2,'A US magazine printed the pairing in 1901, and 1940s ration kits put both spreads in one box.'),
(352,3,'The average American child is said to get through a thousand or so before finishing high school.'),
(352,4,'Two spreads meet on soft white bread, one ground from a roasted legume, the other boiled down from fruit and sugar.'),
(352,5,'Cut corner to corner and sealed in a baggie, the school lunch of America.'),
(353,1,'A bun heaped so high with smoky meat you squash it to bite.'),
(353,2,'The Carolinas have cooked whole hogs over coals since the colonial era, at community gatherings that fed entire towns at once.'),
(353,3,'It starts an argument about sauce: vinegar east, mustard in South Carolina, sweet tomato west.'),
(353,4,'A shoulder rubbed with paprika and brown sugar smokes low and slow until it shreds by hand, then piles on a soft roll.'),
(353,5,'A heaped soft bun with slaw piled on top of the shredded meat, from the American South.');


