INSERT INTO clues (dish_id, order_index, text) VALUES
(354,1,'Tiny hand-rolled bundles passed around before the main course.'),
(354,2,'Cooks across the old Ottoman world wrapped food in leaves this way, and the name comes from a Turkish verb.'),
(354,3,'Every Greek taverna keeps a tray in the cold case, and the tinned kind travelled first.'),
(354,4,'You blanch grape leaves until pliable, roll them tight around rice with dill and mint, and simmer them under a plate.'),
(354,5,'Little green cylinders served cold with a wedge of lemon, passed around in Greece.'),
(355,1,'Crisp shell, soft middle, and sticky fingers afterwards.'),
(355,2,'Ancient Greek writing calls fried dough in honey honey tokens, handed to winners at the earliest games.'),
(355,3,'Athens has shops that have sold nothing else since the 1920s, in paper cones.'),
(355,4,'You drop loose yeasted batter into hot oil a spoon at a time, then drench the puffs in honey syrup.'),
(355,5,'Golden puffs, sticky and eaten hot with a fork, a street sweet in Greece.'),
(356,1,'A plain cookie that waits for icing and sprinkles.'),
(356,2,'German settlers in Nazareth, Pennsylvania baked the round version in the 1700s, and the town''s name stuck.'),
(356,3,'Children decorate them at Christmas and leave a plate out for the visitor down the chimney.'),
(356,4,'Butter creams with egg and vanilla into a pale dough, rolled flat and cut into shapes before it barely colours.'),
(356,5,'America''s smooth, pale cut-outs, crisp at the edge and iced in bright colors for holidays.'),
(357,1,'Soft in the middle, crackled on top, and tangy at the back.'),
(357,2,'New England cookbooks printed it by the late 1800s; the name traces to a German noodle or to plain nonsense.'),
(357,3,'The name gets it picked off the bake-sale table first, on nothing but sound.'),
(357,4,'Cream of tartar gives the dough a distinct tang, and you bake it until it puffs and falls into a crackled top.'),
(357,5,'A cracked-top cookie rolled in cinnamon before it bakes, an American lunchbox treat.'),
(358,1,'A chewy cookie with a healthy reputation and a sweet streak.'),
(358,2,'A cereal company printed a version on its canister around 1900, borrowing from Scottish oatcakes.'),
(358,3,'The internet''s favorite cruel prank, looking exactly like something else until you bite.'),
(358,4,'Rolled oats and dried grapes are folded through a brown sugar and cinnamon dough that bakes chewy rather than crisp.'),
(358,5,'America''s chewy brown disc, studded with rolled grain and dried fruit.'),
(359,1,'Kept warm in a slow cooker at tailgates and holiday gatherings.'),
(359,2,'A bar in western New York gets the 1990s credit, using the sauce that made that city''s wings famous.'),
(359,3,'The bowl is empty at a Super Bowl party before the first quarter ends.'),
(359,4,'Shredded poultry stirs into softened cream cheese with cayenne sauce and cheddar, then bakes until it bubbles.'),
(359,5,'A bubbling orange bowl scooped up with celery and chips, a game-day dish in America.'),
(360,1,'Ordered for the table, scooped up with chips or bread.'),
(360,2,'American chains put it on starter menus in the 1980s, borrowing from older French ways of creaming greens.'),
(360,3,'One chain''s version is among the most searched copycat recipes online.'),
(360,4,'A leafy green and the heart of a thistle chop into cream cheese, sour cream and parmesan, then bake until brown.'),
(360,5,'A hot green bowl, stringy with cheese and served bubbling, ordered at American restaurants.'),
(361,1,'A cold dip for scooping, and nothing in it ever touches the oven.'),
(361,2,'Texas cooks assembled it in the 1970s, and a glass dish made it famous because the stripes show.'),
(361,3,'It is standard potluck and tailgate furniture, and whoever carries it in also carries the biggest bag of chips.'),
(361,4,'Refried beans go down first, then mashed avocado, sour cream, cheese, tomato, olives and scallion, each spread flat.'),
(361,5,'A cold striped glass dish, counted off from the bottom up, brought to American potlucks.'),
(362,1,'A dessert built to rescue the heel of a loaf.'),
(362,2,'English cooks soaked stale loaves like this by the 1200s and called it the poor man''s supper.'),
(362,3,'New Orleans adopted it so completely that half the city''s restaurants finish it with a whiskey sauce.'),
(362,4,'Torn stale loaf soaks in a custard of milk, egg, sugar and vanilla with raisins, then bakes until the top crisps.'),
(362,5,'Britain''s baked square of soaked stale loaf, served warm under sauce.'),
(363,1,'A meal you crack open, crush and soak before you eat it.'),
(363,2,'Rajasthan tells it as a soldier''s meal, dough balls buried in hot sand at dawn and dug up baked.'),
(363,3,'Rajasthani weddings serve it on a leaf plate with clarified butter poured over.'),
(363,4,'Hard wheat-flour balls are baked until they crack open, then crushed, soaked in ghee, and eaten with a spiced stew of lentils.'),
(363,5,'Cracked, ghee-soaked wheat balls dunked into a spiced lentil stew from the Indian desert.'),
(364,1,'A dumpling the whole family folds together on a flour-dusted table.'),
(364,2,'Cooks in Siberia took the idea from their eastern neighbours, and the name means ear bread.'),
(364,3,'Families made hundreds at a time and left them outside to freeze in the snow.'),
(364,4,'Thin unleavened dough pinches around raw minced beef and pork with onion, then boils and arrives with sour cream.'),
(364,5,'Small boiled parcels eaten by the bowlful with sour cream, a Russian winter dish.'),
(365,1,'A doughnut-shop pastry with a crisp crust and a soft, fruity middle.'),
(365,2,'Dutch settlers brought batter-fried fruit to New York, and the bakery counter made it a craggy glazed slab.'),
(365,3,'It leaves the fryer with more crags and crevices than any other pastry in the case, each catching glaze.'),
(365,4,'Chopped orchard fruit and cinnamon fold through a wet dough, drop into hot oil in an untidy lump, and take a glaze.'),
(365,5,'America''s craggy glazed slab, the biggest thing on the doughnut tray.'),
(366,1,'Airy, hollow inside, and filled with cream once it cools.'),
(366,2,'Naples ties it to Saint Joseph''s feast on the 19th of March, and convent kitchens get the credit.'),
(366,3,'Bakery lines run down the block in Italian-American neighborhoods every March.'),
(366,4,'Choux pastry pipes into a ring and fries hollow, then fills with vanilla cream under a candied sour cherry.'),
(366,5,'Italy''s golden doughnut-like ring, a swirl of custard on top and a single dark cherry.');



