INSERT INTO clues (dish_id, order_index, text) VALUES
(367,1,'A grab-and-go breakfast built in a clear cup.'),
(367,2,'The French word once meant a frozen dessert in a mould; American cafeterias borrowed it for layers.'),
(367,3,'McDonald''s put one on the breakfast menu in the 1990s, and airports followed.'),
(367,4,'Thick strained cultured milk spoons into a clear cup in layers with toasted oat clusters and fruit, stripes showing.'),
(367,5,'A tall clear cup of stripes, eaten cold with a long spoon, sold at American cafes.'),
(368,1,'A bowl that steams on the stove and thickens as you stir.'),
(368,2,'Scottish households lived on it for centuries, and American cereal companies put it in a round canister.'),
(368,3,'A man in a wide-brimmed Quaker hat has smiled off that canister for a century.'),
(368,4,'A rolled cereal grain simmers in milk until it thickens, then takes brown sugar, butter and a shake of cinnamon.'),
(368,5,'A plain hot bowl with brown sugar melting into the middle, a breakfast across America.'),
(369,1,'A smooth hot cereal served with a pat of butter.'),
(369,2,'A North Dakota mill was stuck with a by-product in 1893, and the head miller cooked it into breakfast.'),
(369,3,'The box has carried a smiling chef in a white toque for over a century.'),
(369,4,'Finely milled semolina rains into hot milk and you whisk it constantly until it thickens smooth and lump-free.'),
(369,5,'A pale silky porridge with no grain you can see in it, an American childhood breakfast.'),
(370,1,'An egg dish sliced like a pie and packed for picnics.'),
(370,2,'Italian cooks built it to use up whatever was left, and its name is their verb for frying.'),
(370,3,'Italian-American households make it out of whatever the night before left in the pan.'),
(370,4,'Beaten eggs pour over vegetables softening in olive oil, cook slowly without stirring, then finish under the broiler.'),
(370,5,'A thick open-faced egg cake, served in wedges warm or cold, in an Italian home.'),
(371,1,'A warm spiral that you unwind from the outside in, one layer at a time.'),
(371,2,'Swedish bakers had a cardamom-scented version first; Seattle''s mall bakeries piled on the frosting in 1985.'),
(371,3,'Mall bakeries pipe the oven smell into the corridor on purpose, to turn you around mid-concourse.'),
(371,4,'You spread enriched dough with butter and brown sugar, cut it into spirals and bake them shoulder to shoulder.'),
(371,5,'A warm bakery spiral under a cap of cream cheese frosting, from the mall food courts of America.'),
(372,1,'Bakery bread sold by the square and eaten still warm.'),
(372,2,'The name descends from the Latin for hearth bread, and Liguria has claimed it since Roman times.'),
(372,3,'Genoa eats it for breakfast dunked in coffee, which visitors find hard to believe.'),
(372,4,'A wet, slack dough proves in an oiled tray, and you dimple it all over so the pools hold oil and salt.'),
(372,5,'A thick dimpled flatbread, torn into squares off a tray in an Italian bakery.'),
(373,1,'A cold starter so rich it comes in slivers, with something sweet beside it.'),
(373,2,'Egyptian tombs show geese being fattened; the practice reached Rome, then Alsace and southwest France.'),
(373,3,'Some cities ban it outright, and French law protects it as national culinary heritage.'),
(373,4,'The enlarged liver of a fattened duck is deveined, packed into a terrine, cooked gently and chilled for toast.'),
(373,5,'A pale, rich terrine sliced cold onto toast, a French holiday-table tradition.'),
(374,1,'A pudding with a name that makes visitors giggle.'),
(374,2,'Victorian cookbooks had it by the 1840s, and the second half of the name may be an old word for pudding.'),
(374,3,'A British council renamed it on the canteen menu in 2009 and had to change it back.'),
(374,4,'Flour and shredded suet bind with milk and sugar, dotted with dried currants, then steam for hours under hot custard.'),
(374,5,'The hot steamed British suet pudding freckled with dried currants, served in a bowl under a pour of yellow custard.'),
(375,1,'A stew that waits on the back burner until the whole house is home.'),
(375,2,'Dublin cooks recorded it from the 1700s to use up what was left before the Friday fast.'),
(375,3,'Dublin argues only about whether the sausages may be browned first, and traditionally they may not.'),
(375,4,'Pork sausages and rashers of bacon layer with sliced potato and onion, then simmer in stock until everything gives.'),
(375,5,'The pale Dublin stew of whole sausages, bacon, potato and onion, simmered in stock and never once browned.'),
(376,1,'Chopped fine, crunchy at the edges, and ordered with cold beer.'),
(376,2,'Pampanga claims it, and Lucia Cunanan gets the 1970s credit, using what a nearby air base threw out.'),
(376,3,'Anthony Bourdain called it the dish most likely to win the world over, and it arrives spitting.'),
(376,4,'Pig''s head and ears boil, then grill, then chop fine with onion and chili, and arrive on a sizzling plate.'),
(376,5,'A sizzling plate with an egg stirred through it at the table, served in the Philippines.'),
(377,1,'A diner-case slice with a deep red filling that runs onto the plate.'),
(377,2,'Colonists carried the trees over, and Michigan orchards made the sour red kind cheap and canned by the 1940s.'),
(377,3,'A slice and a cup of damn fine coffee is the standing order of an FBI agent in Twin Peaks.'),
(377,4,'Sour red stone fruit thickens with sugar and cornstarch in a butter pastry shell, under strips woven into a lattice.'),
(377,5,'A lattice-topped diner slice, warm under a melting scoop, as served across America.'),
(378,1,'The dessert that closes out a November feast.'),
(378,2,'English colonists filled the native gourd with milk and spices and baked it in the embers.'),
(378,3,'The spice blend invented for it now flavours a coffee chain''s autumn latte.'),
(378,4,'The puree of a large orange gourd whisks with eggs, condensed milk, cinnamon and ginger into a single pastry shell.'),
(378,5,'America''s chilled orange custard tart under a swirl of whipped cream.'),
(379,1,'A pie with a sunny filling under a toasted cloud.'),
(379,2,'A Philadelphia baker named Elizabeth Goodfellow gets the credit for joining the curd and the whipped whites.'),
(379,3,'Church bake sales judge it on how high the peaks stand and whether they wept overnight.'),
(379,4,'Sharp yellow citrus juice cooks with sugar and egg yolks into a thick curd, then takes a crown of browned whites.'),
(379,5,'A towering dessert under a browned cloud of whipped white, from an American bake sale.'),
(380,1,'A no-bake dessert that is mostly sweet, soft and sticky.'),
(380,2,'Cooks at a Sussex restaurant built it in 1971 and spent years correcting people who swore it was older.'),
(380,3,'Cooks boil the unopened tin for hours, and the makers print a warning because the tins can burst.'),
(380,4,'You spread thick boiled-milk caramel on a crumb base, layer sliced banana over it and cover the lot with cream.'),
(380,5,'Britain''s cold caramel-and-banana dessert under a thick drift of cream.'),
(381,1,'A family dinner baked under a crust you can sink a fork into.'),
(381,2,'Cooks stretched the cheap end of the catch with it, and it became a Friday dinner and canteen regular.'),
(381,3,'Every gastropub trying to prove it takes the classics seriously puts it on.'),
(381,4,'Chunks of white and smoked seafood fold into a thick parsley bechamel under a mashed potato lid, forked into ridges.'),
(381,5,'A forked potato crust over a creamy parsley sauce, the Friday supper of Britain.');

