(399,'Irish Stew','irish-stew','Ireland','europe','entree','hot','lamb','["lamb","potato","onion","carrot","thyme","parsley"]'),
(400,'Bigos','bigos','Poland','europe','entree','hot','pork','["sauerkraut","cabbage","pork","sausage","mushroom","prunes","bay leaf"]'),
(401,'Stollen','stollen','Germany','europe','dessert','cold','vegetarian','["flour","butter","raisins","candied peel","almond","marzipan","powdered sugar"]'),
(402,'Bûche de Noël','buche-de-noel','France','europe','dessert','cold','vegetarian','["egg","sugar","flour","cocoa","cream","chocolate","meringue"]'),
