INSERT INTO clues (dish_id, order_index, text) VALUES
(395,1,'A sharp, tangy soup traditionally eaten around Easter.'),
(395,2,'Peasant households soured rye flour in a crock because it cost nothing, and ate the soup right through Lent.'),
(395,3,'Some villages bury a pot of it on Holy Saturday, a mock funeral for forty days of Lent.'),
(395,4,'You stir the soured rye starter into stock with marjoram and garlic, then drop in sausage and half a boiled egg.'),
(395,5,'Poland''s cloudy white bowl, sometimes served in a round loaf with its top sliced off.'),
(396,1,'A chain-restaurant starter that arrives opened like a flower.'),
(396,2,'A Tampa chain put it on the opening menu in 1988 and dressed its dining rooms up as Australian.'),
(396,3,'One vegetable feeds a whole table, and diners tear it apart with their fingers rather than a fork.'),
(396,4,'You soak the cut onion in buttermilk, dredge it in flour spiked with paprika and cayenne, and fry it whole.'),
(396,5,'America''s steakhouse starter, a fried bulb splayed open into petals around a cup of dipping sauce.'),
(397,1,'One pot, one burner, and a table of people reaching in.'),
(397,2,'A dairy cartel pushed it as a national dish in the 1930s, to move more of what its members made.'),
(397,3,'Lose your bread cube off the long fork and table custom says you buy the next round.'),
(397,4,'You rub the pot with garlic, melt gruyere and emmental into white wine, and loosen it with a shot of kirsch.'),
(397,5,'Switzerland''s bubbling caquelon over a burner, ringed by long forks spearing cubes of crusty loaf.'),
(398,1,'Ski-lodge fuel that is mostly cheese and potato.'),
(398,2,'Savoie cheesemakers dreamed it up in the 1980s to sell more reblochon, and dressed it up as an old mountain recipe.'),
(398,3,'Mountain dialect lent it an old word for potato, though the recipe is younger than most of the ski lifts.'),
(398,4,'You layer sliced potato with bacon, onion, cream and a splash of white wine, then crown it with a halved reblochon, rind up.'),
(398,5,'France''s Alpine après-ski supper, bubbling brown in its baking dish with a crackling orange crust.'),
(399,1,'Plain on purpose, and built for a cold night.'),
(399,2,'Cottagers simmered old mutton with roots in a single pot hung over a turf fire, since the hearth held no more.'),
(399,3,'Cooks fight over carrot: purists say mutton, spuds and onion are the whole recipe, and orange is a Dublin affectation.'),
(399,4,'You layer lamb neck chops between rounds of potato and onion, add water and thyme, and simmer it for two hours.'),
(399,5,'Ireland''s pale brothy bowl of floury spuds and tender meat, scattered with parsley beside a hunk of soda bread.'),
(400,1,'Ladled from a crock at winter markets and holiday tables.'),
(400,2,'Noble hunting parties cooked it at camp from whatever they shot, which is why it still goes by hunter''s stew.'),
(400,3,'Families reheat one pot for a week and swear day three is best, and the national epic poem gives it a verse.'),
(400,4,'You simmer sauerkraut and fresh cabbage for hours with pork, sausage, dried mushroom, prunes and bay leaf.'),
(400,5,'Poland''s brown winter hotpot, sharp and smoky, spooned from a crock beside dark rye.'),
(401,1,'A loaf baked in autumn and left to wait for the holidays.'),
(401,2,'Saxon bakers wrote to the Pope asking to use butter during the Advent fast, and a papal letter let them.'),
(401,3,'Bakers shape it to look like the swaddled Christ child, and Dresden parades a giant one through town each December.'),
(401,4,'You knead raisins and candied peel into a yeast dough rich with butter and almond, and roll a log of marzipan into the middle.'),
(401,5,'Germany''s snow-white holiday bread under a thick dusting of powdered sugar, cut in thin slices through Advent.'),
(402,1,'The cake that ends a winter holiday dinner, shaped like firewood.'),
(402,2,'Paris pastry cooks in the 1800s swapped the great block of wood families burned on the hearth for a cake shaped like it.'),
(402,3,'You drag a fork through the frosting to make bark, and little meringue mushrooms sprout along its side.'),
(402,4,'You bake a thin cocoa sponge, roll it around whipped cream, and coat the outside in chocolate ganache.'),
(402,5,'France''s Christmas yule log, one end cut off at a slant like a sawn branch and dusted with sugar snow.'),
(403,1,'Baked once a year for guests who cannot eat it.'),
(403,2,'Families bake it for the first days of November, and historians still argue whether it began as a Spanish or Aztec offering.'),
(403,3,'Bakers lay dough bones across the top and a skull on the crown, and families leave a loaf on home altars for the dead.'),
(403,4,'You scent an egg-rich yeast dough with orange zest and anise, bake it, then brush it with butter and roll it in sugar.'),
(403,5,'Mexico''s bread of the dead, a round sugar-crusted bun sitting on an ofrenda among marigolds and candles.'),
(404,1,'Cold-weather comfort where you choose each piece yourself.'),
(404,2,'Edo vendors took a skewered tofu snack and started simmering it in broth, and the pot grew to hold dozens of items.'),
(404,3,'Convenience store clerks keep a heated tray of it by the till all winter, and you fish out your own pieces with tongs.'),
(404,4,'You simmer daikon, boiled egg, fish cake and konjac in a light dashi seasoned with soy sauce, for hours and never at a boil.'),
(404,5,'Japan''s steaming divided pot of broth-soaked radish and tofu pouches, eaten with a dab of hot yellow mustard.'),
(405,1,'Sticky little rice balls that come in a warm, sweet soup.'),
(405,2,'Families eat them at the winter solstice and the Lantern Festival, a custom going back to the Song dynasty.'),
(405,3,'Diners hear the word for reunion in the name, so a shared bowl on a holiday means the family came home.'),
(405,4,'You wrap black sesame paste creamed with sugar and lard in glutinous rice dough, roll balls, and boil them until they float.'),
(405,5,'China''s glossy white rice balls bobbing in ginger syrup, spilling dark filling when you bite.'),
(406,1,'A cold-season dish where the bitter greens are the point.'),
(406,2,'Punjabi farm households cook it in the cold months, when the leaves come straight off their own winter fields.'),
(406,3,'Cooks pair it with a crumbly flatbread of maize, and you top it with a lump of white butter.'),
(406,4,'You simmer bitter leaves with spinach, ginger and green chili for hours, churn them with a wooden masher, and add cornmeal.'),
(406,5,'India''s dark green mash of mustard greens, glossy with ghee and fried garlic, scooped up with yellow corn roti.'),
(407,1,'A heavy dinner that spends the afternoon in a covered pot.'),
(407,2,'Depression-era families bought the cheapest chuck and let a heavy lidded kettle turn it tender over one long afternoon.'),
(407,3,'An internet version drops a packet of ranch mix and a jar of pepperoncini on top and walks away.'),
(407,4,'You sear a chuck in a Dutch oven, add beef broth, carrot, potato, onion, thyme and bay leaf, and braise it for hours.'),
(407,5,'America''s Sunday dinner, a fork-tender slab sliced beside its vegetables under brown gravy.'),
(408,1,'A holiday side that brings its own crunchy topping.'),
(408,2,'Dorcas Reilly worked it out in a Campbell''s test kitchen in 1955, to sell more cream of mushroom soup.'),
(408,3,'Her family gave the original handwritten card to the National Inventors Hall of Fame, and a museum keeps it there.'),
(408,4,'You stir snapped pods into canned mushroom soup with milk, soy sauce and black pepper, then bake it under crisp fried onion.'),
(408,5,'America''s Thanksgiving side, grey-green and bubbling under a crunchy crown of canned shallots.'),
(409,1,'A sweet that turns a winter vegetable translucent.'),
(409,2,'Anatolian households make it in autumn, when the markets fill with thick-skinned winter squash sold by the slice.'),
(409,3,'Cooks pour tahini over the top and scatter crushed walnuts, a pairing that surprises diners who expect cream.'),
(409,4,'You bury peeled wedges in sugar with a few cloves overnight, then simmer them in their own juice until they turn glassy.'),
(409,5,'Türkiye''s pumpkin dessert, translucent orange slabs under a drizzle of sesame paste and nut crumbs.');

