INSERT INTO clues (dish_id, order_index, text) VALUES
(410,1,'A fried potato side that hitches a ride with almost any fast-food order.'),
(410,2,'Vendors near the Belgian border were frying potato batons by the 1680s, long before the dish crossed the Atlantic.'),
(410,3,'Belgians dunk this side in mayonnaise, not ketchup, and bristle when tourists ask for the red bottle.'),
(410,4,'You cut a potato into batons, soak them to pull out starch, then fry them twice for a shell that stays crisp.'),
(410,5,'America''s fast-food classic, a paper sleeve of golden potato batons dusted with salt.'),
(411,1,'A fried starter that shows up wherever a drive-in flips a burger.'),
(411,2,'A Texas curb-service chain battered and deep-fried sliced onion for parked customers back in the 1920s.'),
(411,3,'Cutting the onion crosswise into loops, not lengthwise into strips, is what gives this snack its shape.'),
(411,4,'The cook dips onion loops in batter and crumbs, then fries them until the coating turns deep gold.'),
(411,5,'An American diner basket of crisp golden loops, stacked beside a bowl of dipping sauce.'),
(412,1,'A breaded fried snack that took over school trays and drive-in menus alike.'),
(412,2,'Fast-food chains built a whole 1980s menu item around a strip of breast muscle cooks once ground into scraps.'),
(412,3,'Only one strip like this comes from each bird, cut from the muscle nearest the breastbone.'),
(412,4,'The cook breads a strip of breast meat, then fries it until the crust cracks and the center stays juicy.'),
(412,5,'An American lunch-counter basket of breaded golden strips, served with a ramekin of dipping sauce.'),
(413,1,'A fried potato side shaped by a school-lunch tray rather than a knife.'),
(413,2,'An Oregon processor in 1953 pressed leftover potato scraps into small cylinders instead of discarding them.'),
(413,3,'The shape is a small cylinder built entirely from potato scraps, never from a whole sliced potato.'),
(413,4,'The cook shreds potato, presses the scraps into short cylinders, and deep-fries them until the outside turns crisp.'),
(413,5,'America''s cafeteria-tray favorite, a pile of crisp golden cylinders beside a pool of ketchup.'),
(414,1,'A soda-fountain dessert served in a tall glass dish.'),
(414,2,'Several towns claim the invention, built to dodge blue laws that banned soda sales on the Sabbath.'),
(414,3,'Every town that claims the invention swears its own soda counter did it first.'),
(414,4,'The fountain worker scoops dessert into a dish, pours on flavored syrup, then tops it with cream and a cherry.'),
(414,5,'America''s soda-fountain classic, a scoop drowned in syrup under cream and a bright red cherry.'),
(415,1,'A fizzy soda-fountain drink where dessert and soda share one glass.'),
(415,2,'A Colorado shopkeeper dropped frozen dessert into his dark, spiced soda in 1893, and it foamed over the rim.'),
(415,3,'The scoop drops into the glass whole and only breaks apart once you start spooning it out.'),
(415,4,'The server pours dark, spice-scented soda over a scoop of frozen dessert and lets the foam rise before serving.'),
(415,5,'America''s fizzy brown glass under a white scoop, sipped through a straw beside a long spoon.'),
(416,1,'A thick blended drink spun up behind a soda-fountain counter.'),
(416,2,'Soda jerks in the 1920s began spinning frozen dessert on an upright mixer into a much thicker drink.'),
(416,3,'The drinker needs a spoon before the straw does any real work.'),
(416,4,'The fountain worker blends milk with ice cream and flavoring on a spindle mixer until it turns thick and pale.'),
(416,5,'America''s tall fluted glass, so dense the straw stands upright, poured with extra in a metal cup.'),
(417,1,'A diner breakfast judged by how brown the underside gets.'),
(417,2,'New England cooks chopped up Monday''s leftover salted meat and boiled potato to build this skillet plate.'),
(417,3,'A fried egg lands on top nine times out of ten, judged by the crust that forms underneath before the flip.'),
(417,4,'The cook dices cured meat with potato and onion, then presses it flat in a hot pan until a crust forms underneath.'),
(417,5,'America''s diner skillet, a browned heap of chopped meat and potato topped with a fried egg.'),
(418,1,'A diner platter big enough to hang over the plate''s edge.'),
(418,2,'German and Austrian settlers in nineteenth-century Texas adapted their breaded veal cutlet to a cheaper cut of beef.'),
(418,3,'The name describes a cooking method, not a bird, which confuses diners expecting poultry on the plate.'),
(418,4,'The cook pounds a tough cut thin, dredges it in seasoned flour, dips it in buttermilk and egg, then cooks it in a skillet.'),
(418,5,'America''s Texas diner plate, a breaded cutlet buried under peppery white gravy beside mashed potato.'),
(419,1,'Ladled out when somebody in the house is under the weather.'),
(419,2,'Depression-era cooks stretched one bird across a whole family by dropping dough balls into the simmering pot.'),
(419,3,'A single bird has to feed a table of six or more, so the pot fills out with dough instead of meat.'),
(419,4,'The cook simmers meat with carrot and celery, then drops spoonfuls of soft dough on top to steam until puffed.'),
(419,5,'The American South''s simmered pot, torn meat and pillowy dough afloat in thick pale broth.'),
(420,1,'Baked in cast iron, crumbly and a little sweet.'),
(420,2,'Indigenous farmers across the Americas ground this dish''s grain into meal centuries before settlers adopted the recipe.'),
(420,3,'Bakers heat the empty skillet in the oven first, so the batter starts sizzling the instant it hits the metal.'),
(420,4,'The baker mixes ground grain with buttermilk and egg, pours it into a scorching skillet, and bakes it until dark.'),
(420,5,'A Southern American wedge, golden and slightly gritty, split open and slicked with melting butter.'),
(421,1,'Creamy without cream, thanks to hours of patient simmering.'),
(421,2,'Creole households in one southern city cooked this pot every washday, using Sunday''s leftover ham bone.'),
(421,3,'A jazz trumpeter from that city signed his letters with a phrase built from this pot''s own name.'),
(421,4,'The cook simmers dried legumes for hours with sausage, onion and celery, then spoons it over steamed grain.'),
(421,5,'America''s Monday pot from Louisiana, a thick reddish stew ladled over white rice with a link of sausage.'),
(422,1,'A red-sauce pan that shows up at graduations and christenings.'),
(422,2,'Immigrant cooks in early-1900s American cities stretched an Italian oven-pasta habit with cheap ground meat.'),
(422,3,'One pan reheats in the dish it baked in and stretches to feed a crowd, which is why potlucks lean on it.'),
(422,4,'The cook tosses tube pasta with tomato sauce and ground meat, layers in two cheeses, and bakes until it browns.'),
(422,5,'An American red-sauce casserole, tubes of pasta bound in melted cheese under a browned, bubbling top.'),
(423,1,'Sold in thick slices from a pizzeria counter, steaming inside.'),
(423,2,'A Pennsylvania pizzeria owner in the 1950s rolled dough around meat and cheese, naming it after a volcanic island.'),
(423,3,'Diners cut it into rounds rather than wedges, since the filling spirals through the dough instead of sitting flat.'),
(423,4,'The cook layers cured meats and cheese onto flattened dough, rolls the sheet into a log, and bakes it until golden.'),
(423,5,'An American pizzeria log, sliced into spirals of melted cheese and cured meat inside a golden crust.'),
(424,1,'Eaten over the wrapper, because it will not stay in the bread.'),
(424,2,'Italian butchers in early-twentieth-century American cities ground scrap cuts into balls, since the whole cut cost too much.'),
(424,3,'The bread has to survive a soaking in sauce without falling apart, which is the real test of the right roll.'),
(424,4,'The cook simmers ground meat in tomato sauce, piles it into a long roll, and melts cheese over it under a broiler.'),
(424,5,'An American deli favorite, a long roll packed with sauced meat and stretched, browned cheese.'),
(425,1,'A spicy sandwich that grew out of a bar snack from upstate New York.'),
(425,2,'A bar in a New York border city tossed fried wings in a butter-hot sauce blend in 1964, and the coating later moved to a roll.'),
(425,3,'The tangy pale cheese served with it once cooled the same sauce on the bar snack, not a sandwich topping.'),
(425,4,'The cook batters and fries a piece, tosses it in a butter-hot sauce blend, and sets it on a roll with cool cheese.'),
(425,5,'America''s upstate New York sandwich, a fiery orange-red cutlet on a soft roll with pale, tangy cheese.'),
(426,1,'A cold sandwich built for lunch counters and church-potluck tables.'),
(426,2,'Boardinghouse cooks in the late 1800s chopped up a cheap breakfast staple and bound it with a creamy sauce for lunch.'),
(426,3,'The filling has almost no crunch on its own, so celery gets folded in to give it something to bite against.'),
(426,4,'The cook chops a boiled staple, binds it with a creamy sauce and mustard, and folds in diced celery.'),
(426,5,'An American deli-counter favorite, a chunky pale yellow filling between two slices of soft bread.'),
(427,1,'Hot, crunchy and gone fast, with a ranch cup beside.'),
(427,2,'Small dairy plants in one Midwestern state started battering fresh cheese pieces and frying them for fairgoers.'),
(427,3,'The pieces squeak against your teeth as you chew, a trait that only lasts before a batch ages into a proper wheel.'),
(427,4,'The cook batters small fresh pieces, drops them in hot oil, and pulls them the moment the shell turns golden.'),
(427,5,'America''s Wisconsin fairground basket, golden nuggets that squeak when you bite through the crisp shell.'),
(428,1,'Scooped from a deep dish while it is still bubbling.'),
(428,2,'Frontier cooks lacking the equipment for a proper pastry lid dropped rough spoonfuls of dough over the fruit instead.'),
(428,3,'The topping is deliberately uneven, dropped rather than rolled, which is what earned this dessert its name.'),
(428,4,'The cook tosses sliced fruit with sugar and spice, drops biscuit dough on top, and bakes it until deep gold.'),
(428,5,'A Southern American dessert, bubbling orange fruit under a craggy, golden biscuit crust.'),
(429,1,'A church-supper dessert that is better the next day.'),
(429,2,'A biscuit company printed the layered recipe on its box in the early 1900s, and Southern cooks kept the layout.'),
(429,3,'The biscuits at the bottom go soft on purpose, soaking into custard until they taste closer to cake than cracker.'),
(429,4,'The cook layers sliced fruit and crisp biscuits with custard, then chills the dish until the biscuits soften.'),
(429,5,'A Southern American trifle dish, sliced fruit and softened wafers under a cloud of whipped cream.'),
(430,1,'A creamy chilled dessert that turns up in nursery kitchens and diner pie cases.'),
(430,2,'Home cooks turned a cheap grain and leftover milk into a nursery dessert, spiced with whatever sat in the cupboard.'),
(430,3,'The grain keeps its shape completely, so every spoonful still carries a bite against the creamy base.'),
(430,4,'The cook simmers grain slowly in milk and sugar until thick and creamy, then stirs in spice and dried fruit.'),
(430,5,'An American comfort bowl, plump pale grains suspended in a sweet, cinnamon-flecked cream.'),
(431,1,'A palm-sized dessert sandwich with cream where the meat would be.'),
(431,2,'Amish farm wives baked spare cake batter into small rounds and packed them with a sweet filling for lunch pails.'),
(431,3,'Farm children are said to have shouted a two-word exclamation on finding one packed in their lunch, and the name stuck.'),
(431,4,'The baker bakes two soft cake-like rounds, spreads a sweet fluffy filling between them, and presses the halves shut.'),
(431,5,'America''s New England farm-stand treat, two dark cake rounds sandwiched around a thick white filling.'),
(432,1,'A no-bake bar dessert that lives in lunchboxes and bake-sale tables.'),
(432,2,'A cereal company employee invented this bar in 1939 for a girls'' club to sell door to door.'),
(432,3,'No oven ever touches the finished bar, since melted binder alone holds the puffed grain together.'),
(432,4,'The cook melts butter and a soft sugary binder, folds in puffed grain cereal, and presses it flat before it sets.'),
(432,5,'An American lunchbox square, pale puffed grain bound into a chewy, faintly sticky bar.'),
(433,1,'A campfire dessert assembled by hand around any fire pit with marshmallows nearby.'),
(433,2,'A 1927 guidebook for a girls'' outdoor club printed the recipe under a name shortened from campers asking for seconds.'),
(433,3,'A stick held over open flame does the only cooking this dessert ever needs, no oven involved.'),
(433,4,'The camper toasts a soft sugary puff over open flame, then presses it with chocolate between two crackers.'),
(433,5,'America''s campfire treat, a molten white puff and melting chocolate squeezed between two crisp crackers.'),
(434,1,'A thick simmered soup built to survive a long, cold-winter haul.'),
(434,2,'Fur traders and lumber camps needed a filling meal that kept without refrigeration, so this dried-legume pot traveled with them.'),
(434,3,'The finished pot turns thick enough that a spoon stands up in it, which is exactly why camps trusted it to travel.'),
(434,4,'The cook simmers a ham bone with peas, onion and carrot for hours until the pot turns thick and green.'),
(434,5,'Canada''s dense green pot from Quebec, a smoky ham bone poking through a thick, velvety puree.'),
(435,1,'Crisp fried nuggets lacquered in a sticky, shiny glaze.'),
(435,2,'A chef at a Hawaii fast-casual chain created this dish in 1987, aiming for a citrus glaze sweeter than sour Hunan sauces.'),
(435,3,'Almost every piece on the plate wears the same glossy sauce, so the fruit in the name rarely shows up as actual fruit.'),
(435,4,'The cook fries battered meat until crisp, then tosses it in a sticky, citrus-sweetened glaze thickened with cornstarch.'),
(435,5,'A Chinese-American takeout carton, glossy citrus-glazed pieces piled over steamed white rice.'),
(436,1,'A quick stir-fried entree that rides home in a folded paper carton.'),
(436,2,'Cantonese cooks who emigrated to nineteenth-century American cities swapped in a Western vegetable their new customers knew.'),
(436,3,'The green vegetable in the name only entered the recipe once the dish crossed the Pacific from Cantonese kitchens.'),
(436,4,'The cook sears thin-sliced meat over high heat, adds chopped florets, and finishes both in a glossy garlic-ginger sauce.'),
(436,5,'A Chinese-American takeout classic, dark glazed strips of meat tangled with bright green florets over rice.'),
(437,1,'A tangled noodle entree tossed to order behind a takeout counter''s glass window.'),
(437,2,'Cantonese cooks named this plate for the tossing motion used to coat cooked strands, not for how the strands were cooked.'),
(437,3,'The strands boil first and only meet sauce afterward in a hot pan, never simmered together like a soupier noodle dish.'),
(437,4,'The cook boils wheat strands separately, then tosses them through a hot pan with shredded vegetables and a dark sauce.'),
(437,5,'China''s takeout-counter tangle, glossy dark strands threaded with slivers of vegetable.'),
(438,1,'A deep-fried appetizer that rounds out almost any combo-plate order.'),
(438,2,'A New York City chef published one of the first English recipes for this thick-skinned fried starter in 1917.'),
(438,3,'The wrapper fries up thick and craggy rather than thin and shattering, unlike its lighter cousin abroad.'),
(438,4,'The cook wraps shredded cabbage and minced meat in a thick wrapper, seals the edge, and deep-fries it until it blisters.'),
(438,5,'A Chinese-American restaurant starter, a blistered golden cylinder cut open to show shredded cabbage inside.'),
(439,1,'A communal simmering meal where the diners do the cooking, not the kitchen.'),
(439,2,'Mongolian cavalry are said to have cooked meals this way over open fires between marches, centuries before it moved indoors.'),
(439,3,'No diner at the table gets a finished plate; each one cooks their own share a few pieces at a time.'),
(439,4,'Diners drop thin-sliced meat, tofu and vegetables straight into a simmering pot and fish them out with chopsticks.'),
(439,5,'China''s shared tabletop pot, a bubbling broth crowded with meat, tofu and vegetables diners cook themselves.'),
(440,1,'A steamed appetizer from Cantonese dim sum kitchens.'),
(440,2,'Cantonese cooks in southern China have steamed dough around a savory filling for teahouse carts since the 1800s.'),
(440,3,'Steam alone puffs the dough, since no oven ever touches this parcel before it reaches the table.'),
(440,4,'The cook steams a pillowy dough parcel over simmering water until it puffs, then fills it with sweet glazed meat.'),
(440,5,'China''s Cantonese teahouse-cart favorite, a pale pillowy parcel pulled open to show glazed meat inside.'),
(441,1,'A fried entree that built a whole late-night delivery culture around one bird.'),
(441,2,'American army bases introduced fried poultry to the region after a mid-century war, and cooks reworked it with a sticky glaze.'),
(441,3,'The crust survives a dunk in sticky glaze without turning soggy, since it gets fried twice before any sauce touches it.'),
(441,4,'The cook fries battered pieces once for structure, fries them again for crunch, then tosses them in a sweet, spicy glaze.'),
(441,5,'South Korea''s late-night delivery order, glossy red-glazed pieces still crackling under the sauce.'),
(442,1,'A fermented side dish that turns sharper and redder the longer it waits.'),
(442,2,'Cooks buried jars of salted vegetables underground through winter long before chili peppers ever reached the peninsula.'),
(442,3,'Some rural households still bury whole jars underground each winter for the flavor the cold ground gives it.'),
(442,4,'The cook salts a leafy vegetable, rubs it with garlic, ginger and chili paste, then packs it into a jar to ferment.'),
(442,5,'South Korea''s tangy side dish, red-flecked leaves packed tight in a jar and served cold at every meal.'),
(443,1,'A skewered street food charred fast over a bed of glowing coals.'),
(443,2,'Vendors at seventeenth-century post towns grilled cheap cuts on sticks for travelers, at a time this bird was frowned on.'),
(443,3,'Bar cooks keep each stick down to one bite, so a whole meal there gets measured in sticks rather than plates.'),
(443,4,'The cook threads bite-size pieces onto a bamboo stick and grills them over charcoal, brushing on a sweet soy glaze.'),
(443,5,'Japan''s smoky charcoal stall, small skewers glazed dark and glistening, stacked in a jar by the register.'),
(444,1,'A breaded cutlet plate eaten with a spoon instead of chopsticks.'),
(444,2,'A European island nation''s navy introduced a spiced Western sauce in the 1800s, and cooks paired it with a breaded cutlet.'),
(444,3,'The sauce underneath is thicker and sweeter than the dish it borrows its spices from, closer to gravy than soup.'),
(444,4,'The cook fries a breaded cutlet until golden, slices it, and sets it over rice under a thick, mild sauce.'),
(444,5,'A Japanese lunch-counter plate, a sliced golden cutlet fanned over rice under a pool of brown sauce.'),
(445,1,'A one-plate stir-fry cooked to order behind a rice-cart''s tiny gas burner.'),
(445,2,'Roadside cart cooks built this fast plate around a fiery peppery herb, distinct from the sweeter herb Western kitchens use.'),
(445,3,'A fried egg with a runny yolk lands on top more than not, breaking over the rice the moment a fork goes in.'),
(445,4,'The cook stir-fries minced meat with garlic and chili, folds in a fistful of peppery leaves at the end, then spoons it over rice.'),
(445,5,'Thailand''s rice-cart plate, minced meat flecked dark green under a fried egg with a runny yolk.'),
(446,1,'A stretched flatbread slapped and spun thin enough to see daylight through it.'),
(446,2,'Immigrant cooks from southern India settled in Southeast Asia and brought the stretched-dough technique with them.'),
(446,3,'A good one is crisp outside and soft in layers, and the cook flips the whole thing in the air.'),
(446,4,'The cook flattens and stretches oiled dough into a thin sheet, folds it into layers, and fries it on a griddle until flaky.'),
(446,5,'Malaysia''s breakfast-stall flatbread, flaky golden layers torn by hand and dipped into a bowl of curry.'),
(447,1,'A birthday and fiesta centerpiece with skin that shatters like glass.'),
(447,2,'Colonizers introduced a whole-animal spit-roasting method centuries ago, and two rival cities still argue whose version is true.'),
(447,3,'A whole animal turns on a spit for hours, so this dish only appears at gatherings large enough to justify one.'),
(447,4,'The cook stuffs the cavity with lemongrass and garlic, then turns the whole animal slowly over open coals until the skin blisters.'),
(447,5,'The Philippines'' festival centerpiece, a whole roasted animal with skin cracked deep amber, carved tableside.'),
(448,1,'A syrup-soaked fried sweet that stains your fingers day-glo orange.'),
(448,2,'Traders carried a coiled, syrup-soaked sweet east from the Middle East centuries ago, and cooks brightened the syrup with saffron.'),
(448,3,'Cooks pipe the batter straight into hot oil in loose spirals, so no two coils ever come out the same shape.'),
(448,4,'The cook pipes fermented batter through hot oil in loose spirals, fries it crisp, then soaks the whole coil in warm syrup.'),
(448,5,'India''s roadside sweet stall, orange spiraled coils glistening with syrup, sold hot off the pan.'),
(449,1,'A slow-cooked dish sold by the kilo at open-air weekend markets.'),
(449,2,'Cooks in one central Mexican state built this dish on simmering meat for hours in its own rendered fat.'),
(449,3,'The meat spends hours barely covered in its own fat rather than water or stock, which is what leaves it easy to shred.'),
(449,4,'The cook simmers cubed pork for hours in rendered fat with orange and garlic, until it turns soft enough to shred.'),
(449,5,'Mexico''s Sunday-market favorite, mounds of shredded meat piled beside crisped edges, ready for a warm tortilla.'),
(450,1,'A slow-braised stew simmered low over a wood fire until the meat falls apart.'),
(450,2,'Colonial-era ranchers in western Mexico stewed a strong-smelling animal Spanish settlers had little other use for.'),
(450,3,'Diners now dunk a folded, cheese-crisped tortilla into the pot''s own broth, turning the stew into its own dipping sauce.'),
(450,4,'The cook braises meat for hours in a dark chili broth with cumin and cinnamon, until it falls apart at the touch of a fork.'),
(450,5,'Mexico''s dark-red stew, tender shredded meat swimming in a rust-colored broth beside a stack of tortillas.'),
(451,1,'A slow-simmered meat sauce plate that changes shape the farther it travels from home.'),
(451,2,'Cooks in the northern Italian city this dish is named for build their version on flat ribbons, largely skipping the round strand.'),
(451,3,'The city credited with the recipe rarely serves it over the long round strand of pasta most of the world pictures.'),
(451,4,'The cook browns ground meat with onion, simmers it with tomato in red wine for hours, then ladles it over long pasta strands.'),
(451,5,'Italy''s name rides on a plate rarely eaten this way at home, long pale strands under a rich, dark red meat sauce.'),
(452,1,'A baked flatbread topping that rides along on nearly every delivery order.'),
(452,2,'Italian-American butchers in early-1900s New York invented a cured sausage unrelated to the sweet peppers its name echoes.'),
(452,3,'The disks curl up at the edges into little cups of fat as they bake, a trick no other common topping pulls off.'),
(452,4,'The cook lays thin-sliced cured sausage over melted cheese and tomato sauce, then bakes it until the disks curl and crisp.'),
(452,5,'America''s pizzeria standard, a round of melted cheese under curled, blistered red-orange disks.'),
(453,1,'A slow-preserved bird dish meant to outlast winter with no refrigerator in sight.'),
(453,2,'Farmhouse cooks with no refrigeration salted a bird''s legs, then cooked them slowly submerged in their own rendered fat.'),
(453,3,'The finished meat used to keep for months at room temperature, sealed under its own fat like a jar of preserves.'),
(453,4,'The cook salts the legs overnight, then cooks them for hours fully submerged in rendered fat until fall-apart tender.'),
(453,5,'Southwestern France''s farmhouse plate, a bronzed leg with skin shattering over meat that falls from the bone.');

-- Dishes that came in through the player suggestion form. Flagged here rather
-- than in the INSERT above so the column list stays as it was; the rest of the
-- catalogue keeps the 0 default. See migrations/0017.
UPDATE dishes SET is_fan_submission = 1
 WHERE slug IN ('fish-and-chips', 'peking-duck', 'souffle',
                'fairy-bread', 'german-chocolate-cake', 'funnel-cake', 'scrambled-eggs',
                'dolmades', 'loukoumades', 'sugar-cookies', 'snickerdoodles',
                'oatmeal-raisin-cookies', 'buffalo-chicken-dip',
                'spinach-and-artichoke-dip', 'seven-layer-dip', 'bread-pudding',
                'dal-baati', 'pelmeni', 'apple-fritter', 'zeppole',
                'yogurt-parfait', 'oatmeal', 'cream-of-wheat', 'frittata',
                'cinnamon-rolls', 'focaccia', 'foie-gras', 'spotted-dick',
                'coddle', 'sisig', 'cherry-pie', 'pumpkin-pie',
                'lemon-meringue-pie', 'banoffee-pie', 'fish-pie',
                'quiche-lorraine', 'lumpia',
                'boat-noodles', 'fuqi-feipian', 'baked-alaska', 'carrot-cake', 'palabok',
                'zurek', 'blooming-onion', 'haggis', 'halo-halo');


